// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep the fuzzed depositor admissible: a plain EOA, distinct from c.
        vm.assume(depositor != address(c));
        vm.assume(depositor.code.length == 0);
        amount = bound(amount, 1, 1e30);

        // Deposit via the fallback from the fuzzed depositor.
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool depOk, ) = address(c).call{value: amount}("");
        vm.assume(depOk); // the reference always accepts plain-EOA deposits

        // Owner (the deployer, this test contract) withdraws everything.
        uint256 ownerBefore = address(this).balance;
        c.withdrawAll();

        // General rule: after any deposit, withdrawAll empties C and pays the owner in full.
        assertTrue(address(c).balance == 0 && address(this).balance == ownerBefore + amount);
    }
}
